function get_ljwz(e) {

  //传入干支,返回干支index,//传入数字,返回干支
  let Gan = new Array("甲", "乙", "丙", "丁", "戊", "己", "庚", "辛", "壬", "癸");
  let Zhi = new Array("子", "丑", "寅", "卯", "辰", "巳", "午", "未", "申", "酉", "戌", "亥");
  let ljjz = []
  let gannn = 0
  let zhizhi = 0
  for (let i = 0; i < 60; i++) {
    ljjz.push(Gan[gannn] + Zhi[zhizhi])
    gannn++
    zhizhi++
    if (gannn == 10) {
      gannn = 0
    }
    if (zhizhi == 12) {
      zhizhi = 0
    }
  }

  if (/.*[\u4e00-\u9fa5]+.*$/.test(e)) {
    //传入干支,返回干支index
    for (let i in ljjz) {
      if (ljjz[i] == e) {
        return i
      }
    }
  } else {
    //传入数字,返回干支
    return ljjz[e];
  }
}

function 取六十四课经(e) {
  // console.log(e)
  var 课体 = e.split("\n")

  var 课体数组 = []
  for (var u in 课体) {
    if (课体[u].indexOf("课体：") != -1) {
      课体数组 = 课体[u]
      课体数组 = 课体数组.split("：")[1]
      课体数组 = 课体数组.split("。")[0]
      课体数组.indexOf(",") != -1 && (课体数组 = 课体数组.split("，"))
      课体数组.indexOf("、") != -1 && (课体数组 = 课体数组.split("、"))
      continue
    }
  }
  let data = api_取六十四课经(课体数组)
  let a = []
  for (let i in data) {
    let d = data[i].split("\n")
    let b = []
    for (let j in d) {
      if (d[j].indexOf(":") != -1) {
        b.push({
          k: d[j].split(":")[0],
          v: d[j].split(":")[1]
        })
      } else {
        b.push({
          k: d[j],
          v: ""
        })
      }
    }
    a.push(b)
  }
  return a
}

