function 取交节月将(节气) {
  //   十二节（节气）	十二气（中气）	公历日期范围
  // 立春（正月节）	雨水（正月中）	2月3日-5日
  // 惊蛰（二月节）	春分（二月中）	3月5日-7日
  // 清明（三月节）	谷雨（三月中）	4月4日-6日
  // 立夏（四月节）	小满（四月中）	5月5日-7日
  // 芒种（五月节）	夏至（五月中）	6月5日-7日
  // 小暑（六月节）	大暑（六月中）	7月6日-8日
  // 立秋（七月节）	处暑（七月中）	8月7日-9日
  // 白露（八月节）	秋分（八月中）	9月7日-9日
  // 寒露（九月节）	霜降（九月中）	10月8日-9日
  // 立冬（十月节）	小雪（十月中）	11月7日-8日
  // 大雪（十一月节）	冬至（十一月中）	12月6日-8日
  // 小寒（十二月节）	大寒（十二月中）	1月5日-7日
  if (节气 == "立春" || 节气 == "雨水") {
    return "亥"
  }
  if (节气 == "惊蛰" || 节气 == "春分") {
    return "戌"
  }
  if (节气 == "清明" || 节气 == "谷雨") {
    return "酉"
  }
  if (节气 == "立夏" || 节气 == "小满") {
    return "申"
  }
  if (节气 == "芒种" || 节气 == "夏至") {
    return "未"
  }
  if (节气 == "小暑" || 节气 == "大暑") {
    return "午"
  }
  if (节气 == "立秋" || 节气 == "处暑") {
    return "巳"
  }
  if (节气 == "白露" || 节气 == "秋分") {
    return "辰"
  }
  if (节气 == "寒露" || 节气 == "霜降") {
    return "卯"
  }
  if (节气 == "立冬" || 节气 == "小雪") {
    return "寅"
  }
  if (节气 == "大雪" || 节气 == "冬至") {
    return "丑"
  }
  if (节气 == "小寒" || 节气 == "大寒") {
    return "子"
  }

}
