function 取三传空(旬空, 三传, 三传神, 神盘) {
  var 空一 = 旬空.charAt(0)
  var 空二 = 旬空.charAt(1)
  var 初传坐空, 中传坐空, 末传坐空, 初传乘空, 中传乘空, 末传乘空 = ""

  if (三传.sc_c == 空一 || 三传.sc_c == 空二) {
    初传坐空 = "⭕"
  } else {
    初传坐空 = ""
  }
  if (三传.sc_z == 空一 || 三传.sc_z == 空二) {
    中传坐空 = "⭕"
  } else {
    中传坐空 = ""
  }
  if (三传.sc_m == 空一 || 三传.sc_m == 空二) {
    末传坐空 = "⭕"
  } else {
    末传坐空 = ""
  }
  // console.log(以神寻宫(三传神.中传神,神盘))
  if (以神寻宫(三传神.sc_sc, 神盘) == 空一 || 以神寻宫(三传神.sc_sc, 神盘) == 空二) {
    初传乘空 = "⨀"
  } else {
    初传乘空 = ""
  }
  if (以神寻宫(三传神.sc_sz, 神盘) == 空一 || 以神寻宫(三传神.sc_sz, 神盘) == 空二) {
    中传乘空 = "⨀"
  } else {
    中传乘空 = ""
  }
  if (以神寻宫(三传神.sc_sm, 神盘) == 空一 || 以神寻宫(三传神.sc_sm, 神盘) == 空二) {
    末传乘空 = "⨀"
  } else {
    末传乘空 = ""
  }
  // console.log(中传坐空,1,中传乘空)
  return {
    chuchuankong: 初传坐空 + 初传乘空,
    zhongchuankong: 中传坐空 + 中传乘空,
    mochuankong: 末传坐空 + 末传乘空
  }

}

function 以神寻宫(神, 神盘) {
  var dz12 = "子丑寅卯辰巳午未申酉戌亥".split("")
  for (var u in dz12) {

    if (神盘['td_' + dz_py(dz12[u]) + "s"] == 神) {
      return dz12[u]
    }
  }
}

function 取四季(节气) {
  if (节气 == "立春" || 节气 == "雨水" || 节气 == "惊蛰" || 节气 == "春分" || 节气 == "清明" || 节气 == "谷雨") {
    return "春"
  }
  if (节气 == "立夏" || 节气 == "小满" || 节气 == "芒种" || 节气 == "夏至" || 节气 == "小暑" || 节气 == "大暑") {
    return "夏"
  }
  if (节气 == "立秋" || 节气 == "处暑" || 节气 == "白露" || 节气 == "秋分" || 节气 == "寒露" || 节气 == "霜降") {
    return "秋"
  }
  if (节气 == "立冬" || 节气 == "小雪" || 节气 == "大雪" || 节气 == "冬至" || 节气 == "小寒" || 节气 == "大寒") {
    return "冬"
  }

}

/**
 *  取四季2(月支)
 */
function 取四季2(月支) {
  return ["冬", "四季", "春", "春", "四季", "夏", "夏", "四季", "秋", "秋", "四季", "冬"][转数字(月支)]
}

function 太阳(年支) {
  return ["丑", "寅", "卯", "辰", "巳", "午", "未", "申", "酉", "戌", "亥", "子",][转数字(年支)]
}

function 排六十甲子(干支) {
  var lj = [{
    jz: ["甲子", "乙丑", "丙寅", "丁卯", "戊辰", "己巳", "庚午", "辛未", "壬申", "癸酉"],
    xs: "子",
    xk: "戌亥",
    xw: "酉"
  },
  {
    jz: ["甲戌", "乙亥", "丙子", "丁丑", "戊寅", "己卯", "庚辰", "辛巳", "壬午", "癸未"],
    xs: "戌",
    xk: "申酉",
    xw: "未"
  },
  {
    jz: ["甲申", "乙酉", "丙戌", "丁亥", "戊子", "己丑", "庚寅", "辛卯", "壬辰", "癸巳"],
    xs: "申",
    xk: "午未",
    xw: "巳"
  },
  {
    jz: ["甲午", "乙未", "丙申", "丁酉", "戊戌", "己亥", "庚子", "辛丑", "壬寅", "癸卯"],
    xs: "午",
    xk: "辰巳",
    xw: "卯"
  },
  {
    jz: ["甲辰", "乙巳", "丙午", "丁未", "戊申", "己酉", "庚戌", "辛亥", "壬子", "癸丑"],
    xs: "辰",
    xk: "寅卯",
    xw: "丑"
  },
  {
    jz: ["甲寅", "乙卯", "丙辰", "丁巳", "戊午", "己未", "庚申", "辛酉", "壬戌", "癸亥"],
    xs: "寅",
    xk: "子丑",
    xw: "亥"
  },
  ]
  for (var i in lj) {
    var data = lj[i]
    var yixun = data.jz
    for (var j in yixun) {
      if (干支 == yixun[j]) {
        return {
          旬首: "甲" + data.xs + "旬",
          旬空: data.xk,
          旬尾: data.xw
        }
      }
    }
  }
}

