function 排四课(天盘, 神盘, 日干, 日支) {
  var 一上, 一下 = 日干,
    一神, 二上, 二下, 二神, 三上, 三下 = 日支,
    三神, 四上, 四下, 四神
  一下 = 日干
  三下 = 日支
  // console.log(天盘,神盘)
  // 'td_'+dz_py(日支)+"t"
  一上 = 天盘['td_' + dz_py(天干寄禄位(日干)) + "t"]
  二下 = 一上
  三上 = 天盘['td_' + dz_py(日支) + "t"]
  四下 = 三上
  二上 = 天盘['td_' + dz_py(一上) + "t"]
  四上 = 天盘['td_' + dz_py(四下) + "t"]
  一神 = 神盘['td_' + dz_py(一上) + "s"]
  二神 = 神盘['td_' + dz_py(二上) + "s"]
  三神 = 神盘['td_' + dz_py(三上) + "s"]
  四神 = 神盘['td_' + dz_py(四上) + "s"]
  var dz = "子丑寅卯辰巳午未申酉戌亥"
  for (var i in dz) {

    if (天盘['td_' + dz_py(dz[i]) + "t"] == 一上) {
      一神 = 神盘['td_' + dz_py(dz[i]) + "s"]
    }
    if (天盘['td_' + dz_py(dz[i]) + "t"] == 二上) {
      二神 = 神盘['td_' + dz_py(dz[i]) + "s"]
    }
    if (天盘['td_' + dz_py(dz[i]) + "t"] == 三上) {
      三神 = 神盘['td_' + dz_py(dz[i]) + "s"]
    }
    if (天盘['td_' + dz_py(dz[i]) + "t"] == 四上) {
      四神 = 神盘['td_' + dz_py(dz[i]) + "s"]
    }
  }
  return {
    sk_1t: 一上,
    sk_1d: 一下,
    sk_1s: 一神,
    sk_2t: 二上,
    sk_2d: 二下,
    sk_2s: 二神,
    sk_3t: 三上,
    sk_3d: 三下,
    sk_3s: 三神,
    sk_4t: 四上,
    sk_4d: 四下,
    sk_4s: 四神
  }
}

