function 排月将(月将, 时支) {
  // console.log(月将, 时支)
  var dz = "子丑寅卯辰巳午未申酉戌亥"
  dz = dz + dz + dz
  var yjs = dz.indexOf(月将)
  var szs = dz.indexOf(时支)
  var vars = {}
  for (var i = 0; i < 12; i++) {
    vars[dz[szs + i]] = dz[yjs + i]
  }
  var dz1 = "子丑寅卯辰巳午未申酉戌亥".split("")
  var obj = {}

  for (let i in dz1) {
    obj['td_' + dz_py(dz1[i]) + "t"] = vars[dz1[i]]
  }
  // console.log(obj)
  return obj
}

function dz_py(e) {
  let t = "zi|chou|yin|mao|chen|si|wu|wei|shen|you|xu|hai".split("|")
  let d = "子丑寅卯辰巳午未申酉戌亥"
  return t[d.indexOf(e)]
}

