function MS_aLon_t(W) { //已知月日视黄经差求时间
  var t, v = 7771.37714500204;
  t = (W + 1.08472) / v;
  t += (W - MS_aLon(t, 3, 3)) / v;
  v = M_v(t) - E_v(t); //v的精度0.5%，详见原文
  t += (W - MS_aLon(t, 20, 10)) / v;
  t += (W - MS_aLon(t, -1, 60)) / v;
  return t;
}

function setFromJD(jd) {
  var r = DD(jd);
  // this.Y=r.Y, 
  // this.M=r.M, 
  // this.D=r.D, 
  // this.m=r.m, 
  // this.h=r.h, 
  // this.s=r.s;  
} //儒略日数转公历
function DD(jd) { //儒略日数转公历
  var r = new Object();
  var D = int2(jd + 0.5),
    F = jd + 0.5 - D,
    c; //取得日数的整数部份A及小数部分F
  if (D >= 2299161) c = int2((D - 1867216.25) / 36524.25), D += 1 + c - int2(c / 4);
  D += 1524;
  r.Y = int2((D - 122.1) / 365.25); //年数
  D -= int2(365.25 * r.Y);
  r.M = int2(D / 30.601); //月数
  D -= int2(30.601 * r.M);
  r.D = D; //日数
  if (r.M > 13) r.M -= 13, r.Y -= 4715;
  else r.M -= 1, r.Y -= 4716;
  //日的小数转为时分秒
  F *= 24;
  r.h = int2(F);
  F -= r.h;
  F *= 60;
  r.m = int2(F);
  F -= r.m;
  F *= 60;
  r.s = F;
  return r;
}

function DD2str(r) { //日期转为串
  var Y = "     " + r.Y,
    M = "0" + r.M,
    D = "0" + r.D;
  var h = r.h,
    m = r.m,
    s = int2(r.s + .5);
  if (s >= 60) s -= 60, m++;
  if (m >= 60) m -= 60, h++;
  h = "0" + h;
  m = "0" + m;
  s = "0" + s;
  Y = Y.substr(Y.length - 5, 5);
  M = M.substr(M.length - 2, 2);
  D = D.substr(D.length - 2, 2);
  h = h.substr(h.length - 2, 2);
  m = m.substr(m.length - 2, 2);
  s = s.substr(s.length - 2, 2);
  return Y + "-" + M + "-" + D + " " + h + ":" + m + ":" + s;
}

function S_aLon_t(W) { //已知太阳视黄经反求时间
  var t, v = 628.3319653318;
  t = (W - 1.75347 - Math.PI) / v;
  v = E_v(t); //v的精度0.03%，详见原文
  t += (W - S_aLon(t, 10)) / v;
  v = E_v(t); //再算一次v有助于提高精度,不算也可以
  t += (W - S_aLon(t, -1)) / v;
  return t;
}

function S_aLon_t2(W) { //已知太阳视黄经反求时间,高速低精度,最大误差不超过600秒
  var t, L, v = 628.3319653318;
  t = (W - 1.75347 - Math.PI) / v;
  t -= (0.000005297 * t * t + 0.0334166 * Math.cos(4.669257 + 628.307585 * t) + 0.0002061 * Math.cos(2.67823 + 628.307585 * t) * t) / v;
  t += (W - E_Lon(t, 8) - Math.PI + (20.5 + 17.2 * Math.sin(2.1824 - 33.75705 * t)) / rad) / v;
  return t;
}
